# PowerShell retry script
param([Parameter(Mandatory=$true)][string]$ModelName)
$maxRetries = 5
$retryCount = 0
while ($retryCount -lt $maxRetries) {
    Write-Host "Attempt $($retryCount + 1)/$maxRetries: Downloading $ModelName..."
    & ollama pull $ModelName
    if ($LASTEXITCODE -eq 0) { exit 0 }
    $retryCount++
    if ($retryCount -lt $maxRetries) { Start-Sleep -Seconds 10 }
}
Write-Host "Failed to download $ModelName after $maxRetries attempts"
exit 1
